	}
	binary := request.OpenCodeBinary
	if binary == "" {
		binary = "opencode"
	}
	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt

	timeout := request.Timeout
	if timeout <= 0 {
