	}
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	args := []string{
		"run",
		"--model", request.Model.ID,
		"--format", "json",
		"--auto",
		"--archived",
		"--title", "ail-bench-"+id,
